'use strict';
// Technical chroma extraction, registration and exact-body head compositing.
// All original character/head artwork was generated by built-in imagegen.
const fs=require('fs'),path=require('path'),crypto=require('crypto');
const sharp=require(process.env.SHARP_PATH||'sharp');
const root=path.resolve(__dirname,'../../../..');
const out=path.join(root,'game/art/buildings/sawmill/v1/life');
const sha=file=>crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
const source=path.join(__dirname,'resting-carpenter-key-master.png');
const crop={left:280,top:48,width:480,height:448};
const resized={width:132,height:198}, placement={left:62,top:28};
const sourceScale=132/1024;
// Alpha>127 hair row94 spansx475..492; last solid sole row1373 spansx540..562.
// Use outer sole boundaryy1374 and its midpointx551 for the physical foot.
const ground=[551,1374],hairTop=[484,94],bodyHeight=ground[1]-hairTop[1];
// Measured head/neck envelope of this carpenter. This is not the hut's mask.
// Lower outline follows skin side of the existing cream neckline.
const polygon=[[325,70],[635,70],[635,260],[570,267],[561,305],
 [552,341],[532,358],[521,386],[509,375],[502,361],[472,364],
 [439,355],[410,339],[393,316],[385,289],[325,282]];
const collarY=79;
function inside(x,y){let yes=false;for(let i=0,j=polygon.length-1;i<polygon.length;j=i++){
 const a=polygon[i],b=polygon[j];if((a[1]>y)!=(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])yes=!yes;
}return yes;}
function stats(data,w,h){const counts={transparent:0,partial:0,opaque:0},boxes={};for(const t of [0,25,127])boxes[t]=[w,h,-1,-1];
 for(let y=0;y<h;y++)for(let x=0;x<w;x++){const a=data[(y*w+x)*4+3];counts[a===0?'transparent':a===255?'opaque':'partial']++;
  for(const t of [0,25,127])if(a>t){const b=boxes[t];b[0]=Math.min(b[0],x);b[1]=Math.min(b[1],y);b[2]=Math.max(b[2],x+1);b[3]=Math.max(b[3],y+1);}}
 return {canvas:[w,h],counts,alpha_bounds_exclusive:boxes};}
async function key(file,keyColor,cutoff){const {data,info}=await sharp(file).removeAlpha().raw().toBuffer({resolveWithObject:true});const rgba=Buffer.alloc(info.width*info.height*4);const kd=Math.min(keyColor[0],keyColor[2])-keyColor[1];
 for(let i=0,p=0;i<data.length;i+=3,p+=4){const r=data[i],g=data[i+1],b=data[i+2],d=Math.min(r,b)-g;const a=d>=cutoff?0:Math.max(0,Math.min(1,(kd-d)/kd));rgba[p+3]=Math.round(a*255);if(!a)continue;
  for(let c=0;c<3;c++)rgba[p+c]=Math.round(Math.max(0,Math.min(255,(data[i+c]-(1-a)*keyColor[c])/a)));}
 return {data:rgba,info,stats:stats(rgba,info.width,info.height)};
}
async function register(data,info){const layer=await sharp(data,{raw:{width:info.width,height:info.height,channels:4}}).resize(resized.width,resized.height,{kernel:'lanczos3'}).png().toBuffer();return sharp({create:{width:256,height:256,channels:4,background:{r:0,g:0,b:0,alpha:0}}}).composite([{input:layer,...placement}]).raw().toBuffer();}
(async()=>{
 fs.mkdirSync(path.join(out,'look'),{recursive:true});
 const original=await key(source,[252,4,251],198);
 const master=path.join(__dirname,'resting-carpenter-rgba-master.png');await sharp(original.data,{raw:{width:original.info.width,height:original.info.height,channels:4}}).png().toFile(master);
 const production=path.join(out,'resting_carpenter.png');const base=await register(original.data,original.info);
 await sharp(base,{raw:{width:256,height:256,channels:4}}).png().toFile(production);
 fs.copyFileSync(production,path.join(out,'look/center.png'));
 const measurements={};
 for(const id of ['left','right']){
  const input=path.join(__dirname,'head-'+id+'-key.png'),head=await key(input,[247,4,248],205);
  const normalized=await sharp(head.data,{raw:{width:head.info.width,height:head.info.height,channels:4}}).resize(crop.width,crop.height,{kernel:'lanczos3'}).raw().toBuffer();
  const combined=Buffer.from(original.data);
  for(let y=0;y<crop.height;y++)for(let x=0;x<crop.width;x++)if(inside(x+crop.left,y+crop.top))normalized.copy(combined,((y+crop.top)*1024+x+crop.left)*4,(y*crop.width+x)*4,(y*crop.width+x+1)*4);
  const candidate=await register(combined,original.info),final=Buffer.from(base);const changedBounds=[256,256,-1,-1];let changed=0,below=0,feet=0;
  for(let y=0;y<256;y++)for(let x=0;x<256;x++){const p=(y*256+x)*4,mx=(x-placement.left+.5)/sourceScale,my=(y-placement.top+.5)/sourceScale;
   if(y<collarY&&inside(mx,my))candidate.copy(final,p,p,p+4);
   if(!final.subarray(p,p+4).equals(base.subarray(p,p+4))){changed++;changedBounds[0]=Math.min(changedBounds[0],x);changedBounds[1]=Math.min(changedBounds[1],y);changedBounds[2]=Math.max(changedBounds[2],x+1);changedBounds[3]=Math.max(changedBounds[3],y+1);if(y>=collarY)below++;if(y>=160)feet++;}}
  const file=path.join(out,'look/'+id+'.png');await sharp(final,{raw:{width:256,height:256,channels:4}}).png().toFile(file);
  measurements[id]={source_sha256:sha(input),production_sha256:sha(file),source_canvas:[head.info.width,head.info.height],key_color:[247,4,248],transparent_dominance_threshold:205,changed_pixels:changed,changed_bounds_exclusive:changedBounds,body_different_pixels_below_collar:below,feet_different_pixels:feet,...stats(final,256,256)};
  if(changed===0||below!==0||feet!==0)throw new Error('Invalid head isolation '+id);
 }
 const groundProduction=ground.map((v,i)=>v*sourceScale+(i?placement.top:placement.left));
 const bodyProduction=bodyHeight*sourceScale;
 const restSprite={texture:'res://art/buildings/sawmill/v1/life/resting_carpenter.png',body_height_px:bodyProduction,ground_contact:groundProduction,look_textures:{left:'res://art/buildings/sawmill/v1/life/look/left.png',right:'res://art/buildings/sawmill/v1/life/look/right.png'}};
 const manifest={date:'2026-09-12',scope:'One resting carpenter body with three head yaw poses, not a directional movement pack',source:'docs/art/sources/carpenter-rest-v1/resting-carpenter-key-master.png',source_sha256:sha(source),master_sha256:sha(master),production_sha256:sha(production),canvas:[256,256],full_source_canvas:[1024,1536],trim:null,resized,placement,source_to_production:sourceScale,source_ground_contact:ground,source_hair_top:hairTop,source_body_height_px:bodyHeight,production_ground_contact:groundProduction,production_body_height_px:bodyProduction,recommended_world_body_height_px:33,recommended_source_px_to_world:33/bodyProduction,technical_alpha:{measured_modal_key:[252,4,251],known_empty_left_band_dominance_range:[206,251],known_empty_top_dominance_range:[223,251],known_hair_patch_dominance_range:[-77,-10],transparent_dominance_threshold:198,method:'Magenta dominance key with straight-alpha unmatte; foreground dominance<=0 fully opaque'},asset_measurements:stats(base,256,256),rest_sprite:restSprite,anatomy:'Bare brown hair, clean shaven, cream rolled-sleeve shirt, dark brown apron, folded empty arms. Weight on anatomical right leg, left boot crossed behind; no held/stowed tool or goods.'};
 fs.writeFileSync(path.join(out,'resting_carpenter.json'),JSON.stringify(manifest,null,2)+'\n');
 const look={date:'2026-09-12',frames:{left:'left.png',center:'center.png',right:'right.png'},size:[256,256],production_ground_contact:groundProduction,production_body_height_px:bodyProduction,source_px_to_world:33/bodyProduction,collar_y:collarY,source_head_polygon_master:polygon,crop_reference:crop,original_sha256:sha(production),body_policy:'Center is byte-identical original PNG; left/right preserve every original RGBA pixel outside this carpenter head mask and at y>=79, including all torso, arms and boots.',measurements};
 fs.writeFileSync(path.join(out,'look/look.json'),JSON.stringify(look,null,2)+'\n');
 const tiles=[];for(const [row,bg]of ['#f4eee2','#171d23','#526334'].entries())for(const [col,id]of ['left','center','right'].entries())tiles.push({input:await sharp({create:{width:256,height:256,channels:4,background:bg}}).composite([{input:path.join(out,'look/'+id+'.png')}]).png().toBuffer(),left:col*256,top:row*256});
 await sharp({create:{width:768,height:768,channels:4,background:'#fff'}}).composite(tiles).png().toFile(path.join(__dirname,'alpha-qa.png'));
 const heads=[];for(const [i,id]of ['left','center','right'].entries())heads.push({input:await sharp(path.join(out,'look/'+id+'.png')).extract({left:98,top:34,width:52,height:49}).resize(312,294,{kernel:'nearest'}).flatten({background:'#66724d'}).png().toBuffer(),left:i*312,top:0});
 await sharp({create:{width:936,height:294,channels:4,background:'#fff'}}).composite(heads).png().toFile(path.join(__dirname,'head-qa-6x.png'));
 const small=[];for(const [i,id]of ['left','center','right'].entries())small.push({input:await sharp(path.join(out,'look/'+id+'.png')).resize(51,51,{kernel:'lanczos3'}).png().toBuffer(),left:20+i*72,top:12});
 const normal=await sharp({create:{width:256,height:80,channels:4,background:'#526334'}}).composite(small).png().toBuffer();
 await sharp(normal).png().toFile(path.join(__dirname,'body33px-qa.png'));
 await sharp(normal).resize(1024,320,{kernel:'nearest'}).png().toFile(path.join(__dirname,'body33px-qa-4x.png'));
 fs.writeFileSync(path.join(__dirname,'export-measurements.json'),JSON.stringify({date:'2026-09-12',source:original.stats,production:manifest.asset_measurements,look,rest_sprite:restSprite},null,2)+'\n');
 console.log(JSON.stringify({rest_sprite:restSprite,production:manifest.asset_measurements,heads:measurements}));
})().catch(e=>{console.error(e);process.exit(1)});
